package com.dahiyalogic.dialer;
import android.app.*;import android.os.*;import android.graphics.Color;import android.telecom.Call;import android.view.*;import android.widget.*;
public class CallActivity extends Activity {
 @Override public void onCreate(Bundle b){super.onCreate(b);setShowWhenLocked(true);setTurnScreenOn(true);LinearLayout l=new LinearLayout(this);l.setPadding(32,90,32,32);l.setOrientation(1);l.setBackgroundColor(Color.rgb(12,19,34));TextView title=new TextView(this);title.setText("📞 Incoming Call\nDAHIYA AI PHONE");title.setTextColor(-1);title.setTextSize(27);l.addView(title);Button yes=new Button(this);yes.setText("ATTEND");l.addView(yes);yes.setOnClickListener(v->{Call c=DahiyaInCallService.active;if(c!=null)c.answer(0);finish();});Button no=new Button(this);no.setText("DECLINE");l.addView(no);no.setOnClickListener(v->{Call c=DahiyaInCallService.active;if(c!=null)c.reject(false,null);finish();});Button ai=new Button(this);ai.setText("AI ATTEND (DEMO)");l.addView(ai);ai.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("AI Attend not yet available").setMessage("Android does not expose cellular call audio to this app. No call has been answered by AI.").setPositiveButton("OK",(d,w)->{}).show());setContentView(l);}
}
